						f.usage()
						return ErrHelp
					}
					return f.failf("unknown shorthand flag: %q in -%s", c, shorthands)
				}
				if bv, ok := flag.Value.(boolFlag); ok && bv.IsBoolFlag() {
					f.setFlag(flag, "true", s)
					continue
				}
